  static String get(String key, String lang) {
    return _localizedValues[lang]?[key] ?? _localizedValues['en']?[key] ?? key;
  }

  static String tr(String key, String langCode) {
    return get(key, langCode);
  }

  static AppLocalizations of(BuildContext context) => const AppLocalizations();
  const AppLocalizations();
  String translate(String key, [String lang = 'en']) => get(key, lang);

  static String localizedRole(String? role, String lang) {
    if (role == null || role.isEmpty) return get('not_available', lang);
    final norm = role.toUpperCase();
    switch (norm) {
      case 'FARMER':
        return get('role_farmer', lang);
      case 'OWNER':
        return get('role_owner', lang);
      case 'ADMIN':
        return get('role_admin', lang);
      default:
        return role;
    }
  }

  static String localizedEquipmentCategory(String? category, String lang) {
    if (category == null || category.isEmpty) return get('not_available', lang);
    final c = category.toLowerCase().trim().replaceAll(' ', '_');
    if (c == 'tractors' || c == 'tractor' || c == 'tractors_and_power_units') return get('tractors', lang).isEmpty ? 'Tractors & Power Units' : get('tractors', lang);
    if (c == 'harvesters' || c == 'harvester' || c == 'harvesting_equipment') return get('harvesters', lang).isEmpty ? 'Harvesting Equipment' : get('harvesters', lang);
    if (c == 'land_preparation' || c == 'land_preparation_equipment') return 'Land Preparation';
    if (c == 'seeding_and_planting' || c == 'seeding_&_planting') return 'Seeding & Planting';
    if (c == 'crop_care_and_interculture' || c == 'crop_care_&_inter-culture_equipment') return 'Crop Care & Interculture';
    if (c == 'irrigation_equipment' || c == 'irrigation') return 'Irrigation Equipment';
    if (c == 'threshing_and_post_harvest' || c == 'threshing_&_post-harvest_equipment') return 'Threshing & Post-Harvest';
    if (c == 'material_handling_and_transport' || c == 'material_handling_&_transport') return 'Transport & Handling';
    if (c == 'soil_testing_and_tools' || c == 'soil_testing_&_measurement_tools') return 'Soil Testing Tools';
    if (c == 'crop_processing' || c == 'crop_processing_equipment') return 'Crop Processing';
    if (c == 'storage_equipment' || c == 'storage') return 'Storage Equipment';
    if (c == 'hand_tools' || c == 'tools') return 'Hand Tools';
    if (c == 'specialized_crop_equipment' || c == 'specialized') return 'Specialized Crop Equipment';
    if (c == 'safety_and_accessories' || c == 'safety_&_accessories') return 'Safety & Accessories';
    if (c == 'power_tillers' || c == 'power_tiller' || c == 'tiller' || c == 'tillers') return get('power_tillers', lang);
    if (c == 'sprayers' || c == 'sprayer') return get('sprayers', lang);
    if (c == 'pump' || c == 'pumps' || c == 'water_pump') return get('pumps', lang);
    if (c == 'cultivator' || c == 'cultivators') return get('cultivators', lang);
    if (c == 'implements' || c == 'implement') return get('implements', lang);
    if (c == 'rotavator' || c == 'rotavators') return get('rotavators', lang);
    if (c == 'thresher' || c == 'threshers') return get('threshers', lang);
    if (c == 'tillage') return get('tillage', lang);
    if (c == 'seeding') return get('seeding', lang);
    if (c == 'seeder' || c == 'seeders' || c == 'seed_drill') return get('seeder', lang);
    if (c == 'plough' || c == 'ploughs' || c == 'plow') return get('plough', lang);
    if (c == 'other') return get('other', lang);
    return category;
  }

  static String localizedCropStage(String? stage, String lang) {
    if (stage == null || stage.isEmpty) return get('not_available', lang);
    final norm = stage.toUpperCase().replaceAll(' ', '_');
    switch (norm) {
      case 'SOWING':
        return get('stage_sowing', lang);
      case 'GERMINATION':
        return get('stage_germination', lang);
      case 'SEEDLING':
        return get('stage_seedling', lang);
      case 'TILLERING':
        return get('stage_tillering', lang);
      case 'VEGETATIVE':
        return get('stage_vegetative', lang);
      case 'PANICLE_INITIATION':
        return get('stage_panicle_initiation', lang);
      case 'FLOWERING':
        return get('stage_flowering', lang);
      case 'FRUITING':
        return get('stage_fruiting', lang);
      case 'MATURITY':
        return get('stage_maturity', lang);
      case 'HARVEST':
        return get('stage_harvest', lang);
      case 'POST_HARVEST':
        return get('stage_post_harvest', lang);
      default:
        return stage.replaceAll('_', ' ');
    }
  }

  static String localizedOperationType(String? opType, String lang) {
    if (opType == null || opType.isEmpty) return get('not_available', lang);
    final norm = opType.toUpperCase().replaceAll(' ', '_');
    switch (norm) {
      case 'LAND_PREPARATION':
        return get('op_land_preparation', lang);
      case 'SEED_SOWING':
        return get('op_seed_sowing', lang);
      case 'TRANSPLANTING':
        return get('op_transplanting', lang);
      case 'IRRIGATION':
        return get('op_irrigation', lang);
      case 'FERTILIZATION':
        return get('op_fertilization', lang);
      case 'WEEDING':
        return get('op_weeding', lang);
      case 'PEST_CONTROL':
        return get('op_pest_control', lang);
      case 'HARVESTING':
      case 'HARVEST':
        return get('op_harvesting', lang);
      case 'POST_HARVEST':
        return get('op_post_harvest', lang);
      default:
        return opType;
    }
  }

  static String localizedBookingStatus(String? status, String lang) {
    if (status == null || status.isEmpty) return get('not_available', lang);
    final st = status.toUpperCase();
    if (st == 'PENDING') return get('pending', lang);
    if (st == 'ACCEPTED' || st == 'CONFIRMED' || st == 'APPROVED') return get('confirmed', lang);
    if (st == 'IN_PROGRESS' || st == 'ACTIVE') return get('active', lang);
    if (st == 'DISPATCHED') return get('dispatched', lang);
    if (st == 'OUT_FOR_DELIVERY') return get('out_for_delivery', lang);
    if (st == 'IN_TRANSIT') return get('in_transit', lang);
    if (st == 'DELIVERED') return get('delivered', lang);
    if (st == 'RETURN_PENDING') return get('return_pending', lang);
    if (st == 'RETURN_IN_PROGRESS') return get('return_in_progress', lang);
    if (st == 'RETURNED') return get('returned', lang);
    if (st == 'INSPECTION_PENDING') return get('inspection_pending', lang);
    if (st == 'COMPLETED') return get('completed', lang);
    if (st == 'REJECTED') return get('rejected', lang);
    if (st == 'CANCELLED') return get('cancelled', lang);
    return status.replaceAll('_', ' ');
  }

  static String localizedPaymentStatus(String? status, String lang) {
    if (status == null || status.isEmpty) return get('not_available', lang);
    final st = status.toUpperCase();
    if (st == 'SUCCESS' || st == 'PAID' || st == 'COMPLETED') return get('paid', lang);
    if (st == 'PENDING') return get('pending', lang);
    if (st == 'FAILED') return get('failed', lang);
    if (st == 'REFUNDED') return get('refunded', lang);
    return status;
  }
}

extension TranslationExtension on String {
  String tr(String lang) {
    return AppLocalizations.get(this, lang);
  }
}

class AppFormatters {
  static const _months = [
    'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
    'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'
  ];

  static String formatCurrency(num? amount, {String? lang}) {
    if (amount == null) return 'N/A';
    if (amount == 0) return '₹0';
    final isNegative = amount < 0;
    final absAmount = amount.abs();
    final parts = absAmount.toStringAsFixed(absAmount.truncateToDouble() == absAmount ? 0 : 2).split('.');
    String intPart = parts[0];
    final decPart = parts.length > 1 ? '.${parts[1]}' : '';

    if (intPart.length > 3) {
      final lastThree = intPart.substring(intPart.length - 3);
      final remaining = intPart.substring(0, intPart.length - 3);
      final chunks = <String>[];
      for (int i = remaining.length; i > 0; i -= 2) {
        final start = (i - 2) < 0 ? 0 : i - 2;
        chunks.insert(0, remaining.substring(start, i));
      }
      intPart = '${chunks.join(',')},$lastThree';
    }
    return '${isNegative ? '-' : ''}₹$intPart$decPart';
  }

  static String currency(num? amount, {String? lang}) {
    if (amount == null) return '₹0';
    return formatCurrency(amount, lang: lang);
  }

  static String formatNumber(num? number) {
    if (number == null) return '0';
    final parts = number.toString().split('.');
    String intPart = parts[0];
    if (intPart.length > 3) {
      final lastThree = intPart.substring(intPart.length - 3);
      final remaining = intPart.substring(0, intPart.length - 3);
      final chunks = <String>[];
      for (int i = remaining.length; i > 0; i -= 2) {
        final start = (i - 2) < 0 ? 0 : i - 2;
        chunks.insert(0, remaining.substring(start, i));
      }
      intPart = '${chunks.join(',')},$lastThree';
    }
    return parts.length > 1 ? '$intPart.${parts[1]}' : intPart;
  }

  static String formatDate(DateTime? date, {String? lang}) {
    if (date == null) return '';
    return '${date.day.toString().padLeft(2, '0')}/${date.month.toString().padLeft(2, '0')}/${date.year}';
  }

  static String formatDateRange(DateTime? start, DateTime? end, {String? lang}) {
    if (start == null && end == null) return 'N/A';
    if (start != null && end == null) {
      return '${start.day} ${_months[start.month - 1]} ${start.year}';
    }
    if (start == null && end != null) {
      return '${end.day} ${_months[end.month - 1]} ${end.year}';
    }
    final s = start!;
    final e = end!;
    if (s.year == e.year && s.month == e.month && s.day == e.day) {
      return '${s.day} ${_months[s.month - 1]} ${s.year}';
    }
    return '${s.day} ${_months[s.month - 1]} – ${e.day} ${_months[e.month - 1]} ${e.year}';
  }
}
